#include <iostream>
#include <vector>

struct Base {
  virtual char kind() const { return 'B'; }
};
struct Derived : Base {
  char kind() const override { return 'D'; }
};

int main() {
  Derived object;
  std::vector<Base> values;
  values.push_back(object);
  const Base& alias = object;
  std::cout << values.front().kind() << alias.kind();
}
